// spec: .qa/e2e/specs/nusach-switch.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

async function counterText(page: Page) {
  const body = await page.locator('body').innerText();
  return (body.match(/\d+ מתוך \d+/) ?? [''])[0];
}

test.describe('Смена нусаха внутри молитвы', () => {
  test('NS-02 Фрагмента нет в другом нусахе → переход к следующему с пояснением #6a86f7d8 @prod-safe @mobile', async ({ page }) => {
    // 1. Открыть `/prayer/mincha_sfarad`; нажимать «קודם», пока не будет «1 מתוך 11» (секция «קרבנות»).
    await page.goto('/prayer/mincha_sfarad');
    await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
    const prev = page.getByText('קודם', { exact: true });
    for (let i = 0; i < 15; i++) {
      if ((await counterText(page)) === '1 מתוך 11') break;
      await prev.click();
    }
    await expect(page.getByText('1 מתוך 11')).toBeVisible();
    await expect(page.getByText('קרבנות', { exact: true })).toBeVisible();

    // 2. Открыть меню нусаха → «אשכנזי».
    await page.getByLabel(/^בחירת נוסח/).click();
    await page.getByRole('radio', { name: 'אשכנזי' }).click();
    const confirm = page.getByRole('alert');
    await expect(confirm).toContainText('הקטע ״קרבנות״ אינו קיים בנוסח אשכנז. התפילה תמשיך מהקטע ״אשרי״');

    // 3. В окне нажать «החלף».
    await confirm.getByRole('button', { name: 'החלף' }).click();
    await expect(page).toHaveURL(/\/prayer\/mincha_ashkenaz/);
    await expect(page.getByRole('heading', { level: 1, name: 'מנחה (אשכנזי)' })).toBeVisible();
    const section = page.getByText('אשרי', { exact: true });
    await expect(section).toBeVisible();
    // текст секции не пустой: после заголовка идёт текст молитвы
    // Порядок огласовок на странице может отличаться от литерала — сравниваем после normalize('NFC') обеих сторон.
    await expect
      .poll(async () => (await page.locator('body').innerText()).normalize('NFC').includes('אַשְׁרֵי יוֹשְׁ֒בֵי בֵיתֶֽךָ'.normalize('NFC')))
      .toBe(true);
  });
});
